Translate("zhCN", "hillsbrad-foothills", {
	title = "希尔斯布莱德丘陵",
	aliases = { "希尔斯布莱德" },
	sections = {
		{
			title = "概述",
			text = [=[希尔斯布莱德丘陵是古老的{link:lordaeron}洛丹伦{/link}王国翠绿的南部边地。它从{link:alterac-mountains}奥特兰克山脉{/link}的积雪一直延伸到温和的海岸。毁灭洛丹伦的瘟疫从这里擦肩而过，有一段时间，希尔斯布莱德似乎幸免于难。但事实并非如此。如今这片丘陵是一片战场。{link:southshore}南海镇{/link}的{link:humans}人类{/link}守着海岸，{link:forsaken}被遗忘者{/link}占据着北方的{link:tarren-mill}塔伦米尔{/link}，而在两者之间，希尔斯布莱德的农场一个接一个地燃起大火。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载最早的村庄何时在这片丘陵中兴起。只要{link:lordaeron}洛丹伦{/link}王国还存在，它们就一直是其一部分。东部边境上矗立着一道古老的城墙，以{link:arathor}阿拉索{/link}的建立者{link:thoradin}索拉丁{/link}之名命名。{link:stormwind-city}暴风城{/link}在{link:first-war}第一次战争{/link}中陷落时，它的难民在{link:southshore}南海镇{/link}登岸，希尔斯布莱德是北方第一片迎接他们的土地。]=],
		},
		{
			title = "当今",
			text = [=[希尔斯布莱德被夹在两场战争之间。{link:high-executor-darthalia}高级执行官达萨利亚{/link}以{link:sylvanas-windrunner}黑暗女王{/link}和{link:varimathras}瓦里玛萨斯{/link}之名统领{link:tarren-mill}塔伦米尔{/link}的{link:forsaken}被遗忘者{/link}。她的亡灵卫兵袭击{link:hillsbrad-fields}希尔斯布莱德农场{/link}的田庄，{link:royal-apothecary-society}皇家药剂师协会{/link}的药剂师则在农民和他们的牲畜身上试验新的毒药。{link:southshore}南海镇{/link}和{link:dun-garok}丹加洛克{/link}的{link:dwarves}矮人{/link}以手头仅有的少量士兵还击。与此同时，{link:syndicate}辛迪加{/link}盘踞在{link:durnholde-keep}敦霍尔德城堡{/link}的废墟中，对双方都下手劫掠。人们认为，他们的刺客已经谋杀了南海镇的一位法官，如今又在追杀下一位。{link:thrall}萨尔{/link}亲自派遣的{link:orcs}兽人{/link}最近来到了塔伦米尔，因为敦霍尔德曾是这位大酋长的牢笼，而他想从那里取回某样东西。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:southshore}南海镇{/link}的居民。{/b}渔民、士兵和学者，忠于{link:alliance}联盟{/link}。
• {b}希尔斯布莱德的农民。{/b}他们仍在河西的田地里劳作，处于敌人的眼皮之下。
• {b}{link:forsaken}被遗忘者{/link}。{/b}他们的亡灵卫兵、亡灵{link:sentinels}哨兵{/link}和药剂师占据着{link:tarren-mill}塔伦米尔{/link}。
• {b}{link:horde}部落{/link}的{link:orcs}兽人{/link}。{/b}一小队从{link:durotar}杜隆塔尔{/link}派来的兽人，以及一名在塔伦米尔默默干活的铁匠。
• {b}{link:dun-garok}丹加洛克{/link}的矮人。{/b}东南方的一支{link:dwarves}矮人{/link}驻军，誓言保卫{link:humans}人类{/link}和他们的矿洞。
• {b}{link:syndicate}辛迪加{/link}。{/b}为{link:alterac-mountains}奥特兰克{/link}那些失势的领主效力的盗贼和暗影法师。
• {b}野兽与劫掠者。{/b}{link:western-strand}西部海岸{/link}的{link:murlocs}鱼人{/link}，{link:eastern-strand}东部海滩{/link}的{link:naga}纳迦{/link}，{link:nethander-stead}奈杉德哨岗{/link}的{link:gnolls}豺狼人{/link}，以及从奥特兰克下山来的{link:ogres}食人魔{/link}。]=],
		},
		{
			title = "历史",
			text = [=[• {b}难民。{/b}{link:stormwind-city}暴风城{/link}陷落后，幸存者渡海在{link:southshore}南海镇{/link}登岸。从那里，{link:orcs}兽人{/link}的消息被送到了国王{link:terenas-menethil}泰瑞纳斯·米奈希尔{/link}面前。
• {b}第二次战争。{/b}{link:anduin-lothar}安度因·洛萨{/link}在希尔斯布莱德集结了{link:alliance}联盟{/link}的大军。{link:horde}部落{/link}在南海镇附近登陆，两军在这里展开了{link:second-war}第二次战争{/link}中第一场大规模陆战。部落的死亡骑士也是在这里第一次与{link:uther-the-lightbringer}光明使者乌瑟尔{/link}的圣骑士交锋。
• {b}{link:internment-camps}收容所{/link}。{/b}战后，{link:durnholde-keep}敦霍尔德城堡{/link}成为关押战败兽人的收容所的中枢。一个名叫{link:thrall}萨尔{/link}的年轻兽人在它的厅堂中作为奴隶长大。他逃了出去，又率领一支新的部落归来，将城堡夷为废墟。
• {b}当今。{/b}{link:lordaeron}洛丹伦{/link}已不复存在，就连它南方的丘陵也正从{link:humans}人类{/link}手中滑落。]=],
		},
		{
			title = "丘陵传说",
			text = [=[• {link:southshore}南海镇{/link}的人说，他们的厨师是{link:stormwind-city}暴风城{/link}以北最好的。有旅人远从{link:darkshire}夜色镇{/link}赶来，只为喝一碗杰森大厨的海龟浓汤。
• 一个名叫{link:helcular}赫尔库拉{/link}的巫师葬在南海镇的墓地里。他的黑暗仪式尚未完成，就被一群镇民杀死了。{link:tarren-mill}塔伦米尔{/link}有人想要完成它。]=],
		},
	},
})

Translate("zhCN", "southshore", {
	title = "南海镇",
	sections = {
		{
			title = "概述",
			text = [=[南海镇是{link:hillsbrad-foothills}希尔斯布莱德{/link}南岸的一座港口小镇，围绕着港口、旅店和市政厅而建。{link:stormwind-city}暴风城{/link}的难民在此登岸时，它还是一个渔村。它至今仍忠于{link:alliance}联盟{/link}，如今是北方最后的{link:humans}人类{/link}城镇之一。{link:magistrate-henry-maleb}赫尼·马雷布镇长{/link}治理着它，{link:marshal-redpath}治安官雷德帕斯{/link}统领它的卫兵。{link:syndicate}辛迪加{/link}发誓要毁灭它，{link:tarren-mill}塔伦米尔{/link}的{link:forsaken}被遗忘者{/link}公开宣称，在希尔斯布莱德之后，南海镇也将被焚毁。]=],
		},
		{
			title = "港口",
			text = [=[狮鹫从镇上的山丘起飞。最近，新的船只开始停靠它的码头，驶往{link:menethil-harbor}米奈希尔港{/link}和遥远的{link:kalimdor}卡利姆多{/link}的{link:auberdine}奥伯丁{/link}。一位{link:kirin-tor}肯瑞托{/link}的使者也已来到镇上住下。]=],
		},
	},
})

Translate("zhCN", "tarren-mill", {
	title = "塔伦米尔",
	sections = {
		{
			title = "概述",
			text = [=[塔伦米尔曾是{link:lordaeron}洛丹伦{/link}的一座{link:humans}人类{/link}城镇，坐落在{link:alterac-mountains}奥特兰克{/link}下方丘陵的果园之间。它的教堂和房屋仍然矗立，但果园已经枯萎，居民也都是亡者。{link:forsaken}被遗忘者{/link}将它作为在南方的据点。{link:high-executor-darthalia}高级执行官达萨利亚{/link}在这里向{link:hillsbrad-foothills}希尔斯布莱德{/link}开战，{link:royal-apothecary-society}皇家药剂师协会{/link}的药剂师在这里调制他们的瘟疫。蝙蝠载着骑手飞往{link:undercity}幽暗城{/link}。一队由{link:thrall}萨尔{/link}派遣的{link:orcs}兽人{/link}也在镇中扎营，因为{link:durnholde-keep}敦霍尔德{/link}的废墟就在河对岸。]=],
		},
	},
})

Translate("zhCN", "durnholde-keep", {
	title = "敦霍尔德城堡",
	aliases = { "敦霍尔德" },
	sections = {
		{
			title = "概述",
			text = [=[敦霍尔德城堡曾是{link:lordaeron}洛丹伦{/link}南部最坚固的要塞。{link:second-war}第二次战争{/link}之后，它成为关押战败{link:orcs}兽人{/link}的{link:internment-camps}收容所{/link}的中枢，由中将{link:aedelas-blackmoore}埃德拉斯·布莱克摩尔{/link}统治。年幼的{link:thrall}萨尔{/link}就在这里作为奴隶长大。当他以大酋长的身份归来时，他摧毁了城墙，把城堡的领主埋在了石块之下。{link:syndicate}辛迪加{/link}占据了这片废墟。他们的暗影法师在那里活动，他们的狱卒把兽人囚犯关在旧牢房里。一个名叫戈格拉什的兽人最近从他们手中逃脱，正在城墙附近等候。]=],
		},
	},
})

Translate("zhCN", "hillsbrad-fields", {
	title = "希尔斯布莱德农场",
	sections = {
		{
			title = "概述",
			text = [=[希尔斯布莱德农场是河西的农田，其中心坐落着{link:hillsbrad-foothills}希尔斯布莱德{/link}镇。镇上的法官{link:magistrate-burnside}伯恩赛德{/link}和他的{link:shadow-council}议会{/link}保管着小镇古老的宪章《希尔斯布莱德宣言》以及它的公民名册。镇上的铁匠铺囤积着一批铁料。这里的农场养活了整片丘陵。正因如此，{link:forsaken}被遗忘者{/link}首先向这里发动袭击。亡灵卫兵袭击北方的农场，农民逃进南方的果园，而小镇在等待一场它无望抵挡的进攻。]=],
		},
	},
})

Translate("zhCN", "azurelode-mine", {
	title = "碧玉矿洞",
	sections = {
		{
			title = "概述",
			text = [=[碧玉矿洞位于{link:hillsbrad-foothills}希尔斯布莱德{/link}以南的丘陵中，俯瞰{link:western-strand}西部海岸{/link}。它的铁矿供应着{link:alliance}联盟{/link}的{link:the-cauldron}熔炉{/link}。工头邦兹督促矿工们干活，{link:sentinels}哨兵{/link}守在矿口。联盟拼命保护它。{link:forsaken}被遗忘者{/link}极想得到它。{link:sylvanas-windrunner}黑暗女王{/link}需要铁来武装她的士兵，而从{link:humans}人类{/link}手中夺来的矿洞正好能给她这些。矿工们有理由害怕。他们工头的名字就在高级执行官的名单上。]=],
		},
	},
})

Translate("zhCN", "dun-garok", {
	title = "丹加洛克",
	sections = {
		{
			title = "概述",
			text = [=[丹加洛克是{link:hillsbrad-foothills}希尔斯布莱德{/link}东南部的一座{link:dwarves}矮人{/link}要塞，背靠{link:thoradin-s-wall}索拉丁之墙{/link}而建。它由山地人、火枪手和牧师组成的驻军由{link:captain-ironhill}达伦·铁山上尉{/link}率领。矮人们前来帮助丘陵中的{link:humans}人类{/link}，守卫着他们的土地。他们酿造一种烈性黑啤酒，而且一旦发现某个粗心的{link:forsaken}被遗忘者{/link}斥候的装备，也不介意顺手拿走。{link:tarren-mill}塔伦米尔{/link}把他们视为最可恶的敌人之一。它的命令很明确：丹加洛克必须陷落。]=],
		},
	},
})

Translate("zhCN", "nethander-stead", {
	title = "奈杉德哨岗",
	sections = {
		{
			title = "概述",
			text = [=[奈杉德哨岗是{link:southshore}南海镇{/link}以东、河对岸的一处废弃农场。没有任何记载说明奈杉德一家的下落。如今泥嘴{link:gnolls}豺狼人{/link}住在它的田地里，一种名为泥嘴花的苍白蘑菇在杂草间长得茂密。这些花奇臭无比，而{link:tarren-mill}塔伦米尔{/link}的药剂师看重的正是这一点。它们是协会最致命的药剂之一的核心。{link:apothecary-lydon}药剂师林度恩{/link}曾说，那些肮脏的豺狼人终究还是有点用处的。]=],
		},
	},
})

Translate("zhCN", "purgation-isle", {
	title = "赎罪岛",
	sections = {
		{
			title = "概述",
			text = [=[赎罪岛是{link:hillsbrad-foothills}希尔斯布莱德{/link}西{link:southsea-pirates}南海{/link}岸外的一座陡峭岛屿，岛顶是一座废弃的高塔，四周环绕着一片古老的墓地。岛上的死者不得安息。被定罪的教士、武僧和侍僧行走于坟墓之间，与受诅咒的圣骑士、审判官和扭曲的法师为伍。他们的力量强大，远远超过大陆上的野兽与劫掠者。没有任何编年史记载他们生前是谁，是什么罪行或厄运将他们束缚在岛上，又为何有如此多的{link:holy-light}圣光{/link}仆从身在其中。]=],
		},
	},
})

Translate("zhCN", "darrow-hill", {
	title = "达隆山",
	sections = {
		{
			title = "概述",
			text = [=[达隆山耸立在{link:hillsbrad-foothills}希尔斯布莱德{/link}北部，位于{link:alterac-mountains}奥特兰克{/link}{link:razorfen-downs}高地{/link}之下。山狮和雄鹿在它的山坡上漫游，雪人盘踞在其上方的洞穴中。这是一片荒野，山上没有城镇。巫师{link:helcular}赫尔库拉{/link}正是在这片山中藏着他的秘密巢穴，直到{link:southshore}南海镇{/link}的镇民找到了他。此后雪人占据了他的洞穴，而他的仪式之火仍在黑暗中燃烧。那个巢穴是个秘密，没有任何记载说明镇民是如何得知它的。]=],
		},
	},
})

Translate("zhCN", "eastern-strand", {
	title = "东部海滩",
	sections = {
		{
			title = "概述",
			text = [=[东部海滩是{link:southshore}南海镇{/link}以东的岩石海岸，一路向下延伸到{link:dun-garok}丹加洛克{/link}。刺脊{link:naga}纳迦{/link}从海中爬上来，占据了这里。他们的海妖和海岸潜伏者沿着海滩狩猎，其中还有一位力量罕见、名叫泽菲利斯女士的纳迦。南海镇的军官们担心纳迦的图谋，有关他们的消息已经传到了{link:alliance}联盟{/link}最高指挥部。南海镇没有人说得清纳迦从何而来。]=],
		},
	},
})

Translate("zhCN", "western-strand", {
	title = "西部海岸",
	sections = {
		{
			title = "概述",
			text = [=[西部海岸是{link:southshore}南海镇{/link}以西的漫长海岸，位于{link:azurelode-mine}碧玉矿洞{/link}之下。裂鳍{link:murlocs}鱼人{/link}沿着海岸建起了营地，离小镇近得足以让卫兵担忧。{link:marshal-redpath}治安官雷德帕斯{/link}想把它们赶回去，并要求以它们的头颅为证。他的副官宁可喝酒也不愿出动，这差事往往落到外乡人头上。这位副官已经好几个星期没吃过鱼了。这个部族中一个名叫斯卡基尔的鱼人很少露面，但见过他的人很少会忘记他。]=],
		},
	},
})

Translate("zhCN", "southpoint-tower", {
	title = "南点哨塔",
	sections = {
		{
			title = "概述",
			text = [=[南点哨塔是{link:hillsbrad-foothills}希尔斯布莱德{/link}最西端的一座废弃瞭望塔，位于通往{link:silverpine-forest}银松森林{/link}的路上。它曾守卫着通往丘陵的要道。如今它只藏着一名{link:forsaken}被遗忘者{/link}斥候。{link:deathstalker-lesh}亡灵哨兵莱什{/link}从它残破的墙后监视着希尔斯布莱德镇，并向东方的{link:tarren-mill}塔伦米尔{/link}传递消息。她孤身一人，远离任何援助，四周全是{link:alliance}联盟{/link}的道路。她的最后一条消息很简短。它说，出击的时刻已经到来。]=],
		},
	},
})

Translate("zhCN", "thoradin-s-wall", {
	title = "索拉丁之墙",
	sections = {
		{
			title = "概述",
			text = [=[索拉丁之墙是一道残破的巨大城墙，将{link:hillsbrad-foothills}希尔斯布莱德丘陵{/link}与{link:arathi-highlands}阿拉希高地{/link}分隔开来。它以{link:arathor}阿拉索{/link}的第一位国王{link:thoradin}索拉丁{/link}之名命名，比如今存在的任何王国都更为古老。大多数人说，它是为了抵御阿曼尼{link:trolls}巨魔{/link}而修建的。它的石块已经开裂，塔楼也已消失，但它仍然标志着边界。{link:dun-garok}丹加洛克{/link}的{link:dwarves}矮人{/link}在它的阴影下建起了要塞。前往阿拉希高地的旅人至今仍须穿过它。]=],
		},
	},
})

Translate("zhCN", "aedelas-blackmoore", {
	title = "埃德拉斯·布莱克摩尔",
	subtitle = "敦霍尔德之主",
	allegiance = "洛丹伦王国 · 敦霍尔德城堡",
	aliases = { "布莱克摩尔" },
	sections = {
		{
			title = "概述",
			text = [=[埃德拉斯·布莱克摩尔是{link:durnholde-keep}敦霍尔德城堡{/link}的领主，也是{link:second-war}第二次战争{/link}后关押战败{link:orcs}兽人{/link}的{link:internment-camps}收容所{/link}的主宰。他是一名凶悍的战士，一个嗜酒之徒，也是一个野心勃勃的人。他在荒野中发现了一个成了孤儿的兽人婴儿，把他当作奴隶养大。那个兽人就是{link:thrall}萨尔{/link}。布莱克摩尔想让他成为一件武器。然而萨尔却成了解放兽人并杀死他的大酋长。]=],
		},
		{
			title = "意义",
			text = [=[布莱克摩尔造就了{link:thrall}萨尔{/link}，只是方式全都出乎他的意料。他的残忍让年轻的{link:orcs}兽人{/link}知道了{link:humans}人类{/link}可以是什么样子。而他自己家中其他人的善意，又让萨尔知道人类也可以是另一种样子。没有布莱克摩尔，就不会有萨尔；没有萨尔，就不会有新的{link:horde}部落{/link}。]=],
		},
		{
			title = "叛徒之子",
			text = [=[布莱克摩尔在{link:second-war}第二次战争{/link}中骁勇善战，以对{link:orcs}兽人{/link}的狂怒而闻名。然而他背负着一个沉重的姓氏。他的父亲曾被判叛国罪，流言蜚语伴随了这个儿子一生。他靠喝酒来面对战斗，战争结束后喝得更凶。当他得到{link:durnholde-keep}敦霍尔德{/link}和{link:internment-camps}收容所{/link}时，他的权力增长了，他的恶习也随之增长。]=],
		},
		{
			title = "兽人之子",
			text = [=[布莱克摩尔与他的仆人塔米斯·福克斯顿一同狩猎时，在一个{link:orcs}兽人{/link}婴儿被杀害的父母的尸体间发现了他。他把孩子带回{link:durnholde-keep}敦霍尔德{/link}，给他取名{link:thrall}萨尔{/link}。他让人教这个孩子读书、写字和战斗，又把他送进{link:gurubashi-arena}竞技场{/link}，与其他领主的冠军对决。私下里，他梦想得更多。萨尔有朝一日将率领一支来自{link:internment-camps}收容所{/link}的兽人大军，而布莱克摩尔将通过他来统治。他对这个孩子常常残忍，偶尔仁慈，却从未像萨尔那样看出两者的区别。]=],
		},
		{
			title = "敦霍尔德的陷落",
			text = [=[{link:thrall}萨尔{/link}在塔米斯的女儿{link:taretha-foxton}塔雷莎·福克斯顿{/link}的帮助下逃脱；布莱克摩尔曾违背她的意愿，强迫她做了自己的情妇。多年以后，这个{link:orcs}兽人{/link}率领一支自由的{link:horde}部落{/link}归来，一个接一个地摧毁了{link:internment-camps}收容所{/link}。围攻前夜，布莱克摩尔得知塔雷莎曾秘密与萨尔会面。他下令处死了她。当萨尔来到城门前谈判时，喝醉的布莱克摩尔把她的头颅从城墙上扔了下去。兽人们攻入了城堡。萨尔在城堡内找到布莱克摩尔，在单挑中杀死了他。随后他召唤大地之灵，{link:durnholde-keep}敦霍尔德{/link}便倒塌在它主人的尸体之上。]=],
		},
	},
	chapters = {
		{
			title = "布莱克摩尔的遗产",
			hint = "查明辛迪加之主对兽人有何图谋。",
			text = [=[布莱克摩尔的野心并没有随他一同死去。被{link:syndicate}辛迪加{/link}囚禁的{link:orcs}兽人{/link}{link:gol-dir}高迪尔{/link}得知，辛迪加的首领{link:lord-aliden-perenolde}奥里登·匹瑞诺德{/link}称布莱克摩尔为自己的导师。匹瑞诺德打算把与他作对的兽人收为奴隶，正如他的父亲和他的老师在他之前所计划的那样。]=],
		},
	},
	mentions = {
		{ text = "布莱克摩尔的遗产" },
		{ text = "{link:lord-aliden-perenolde}奥里登·匹瑞诺德领主{/link}" },
	},
	bonds = {
		{ id = "thrall", name = "萨尔", note = "他的奴隶，也是杀死他的人" },
		{ id = "taretha-foxton", name = "塔雷莎·福克斯顿", note = "他的情妇，被他下令杀害" },
		{ id = "aliden-perenolde", name = "奥里登·匹瑞诺德", note = "他的学生" },
		{ id = "durnholde-keep", name = "敦霍尔德城堡", note = "他的要塞，也是他的坟墓" },
	},
})

Translate("zhCN", "taretha-foxton", {
	title = "塔雷莎·福克斯顿",
	subtitle = "萨尔的朋友",
	allegiance = "敦霍尔德城堡",
	aliases = { "塔雷莎", "塔丽" },
	sections = {
		{
			title = "概述",
			text = [=[塔雷莎·福克斯顿是{link:durnholde-keep}敦霍尔德城堡{/link}的一个女孩，{link:aedelas-blackmoore}布莱克摩尔{/link}的仆人塔米斯·福克斯顿的女儿。对年轻的{link:thrall}萨尔{/link}来说，她是他所知道的最接近家人的人。他身为奴隶时，她偷偷给他写信；她帮助他逃脱，又以自己的生命为他的自由付出了代价。]=],
		},
		{
			title = "意义",
			text = [=[{link:thrall}萨尔{/link}从{link:aedelas-blackmoore}布莱克摩尔{/link}身上懂得了什么是残忍。他从塔雷莎身上懂得了{link:humans}人类{/link}也可以是善良的。正是因为对她的怀念，{link:horde}部落{/link}的大酋长从未憎恨全人类。]=],
		},
		{
			title = "事迹",
			text = [=[• 她还是个孩子时，就发现那个{link:orcs}兽人{/link}婴儿吃不下给他的肉，从而救了他的命。她的母亲哺育了他。
• 她把纸条藏在带到{link:thrall}萨尔{/link}牢房的书中，他们相互通信了许多年。
• 萨尔逃离{link:durnholde-keep}敦霍尔德{/link}时，她点了一把火来分散注意力，并留给他一件斗篷以便通过城门。她不肯与他同行，因为她担心{link:aedelas-blackmoore}布莱克摩尔{/link}会对她的家人下手。
• 在萨尔的大军抵达敦霍尔德的前一夜，她秘密地与萨尔见了面。布莱克摩尔派人跟踪了她，并下令杀了她。]=],
		},
		{
			title = "未载",
			text = [=[没有任何记载说明塔雷莎的吊坠是如何落入{link:alterac-mountains}奥特兰克{/link}领主之手的，也没有记载塔雷莎葬在何处。]=],
		},
	},
	chapters = {
		{
			title = "塔雷莎的礼物",
			hint = "找回大酋长想要的那个吊坠。",
			text = [=[在她死后很久，{link:thrall}萨尔{/link}派来的{link:orcs}兽人{/link}来到{link:hillsbrad-foothills}希尔斯布莱德{/link}，只为寻找一个曾属于她的吊坠。他们在{link:lord-aliden-perenolde}奥里登·匹瑞诺德{/link}的情妇{link:elysa}艾丽萨{/link}的脖子上找到了它。她欣然交了出来。接过它的兽人无法理解，为什么大酋长要为这样一件小东西付出这么多。]=],
		},
	},
	mentions = {
		{ text = "{link:aedelas-blackmoore}布莱克摩尔{/link}的遗产" },
		{ text = "{link:lord-aliden-perenolde}奥里登·匹瑞诺德领主{/link}" },
		{ text = "塔雷莎的礼物" },
	},
	bonds = {
		{ id = "thrall", name = "萨尔", note = "她的朋友，她称他为兄弟" },
		{ id = "aedelas-blackmoore", name = "埃德拉斯·布莱克摩尔", note = "她的主人，也是杀害她的凶手" },
		{ id = "krusk", name = "克鲁斯克", note = "为大酋长找回了她的吊坠" },
	},
})

Translate("zhCN", "loremaster-dibbs", {
	title = "博学者迪布斯",
	subtitle = "南海镇的学者",
	found = "南海镇",
	hint = "寻找南海镇的老学者。",
	allegiance = "南海镇 · 联盟",
	aliases = { "迪布斯" },
	sections = {
		{
			title = "概述",
			text = [=[博学者迪布斯是{link:southshore}南海镇{/link}的学者，一位与书为伴的老人；在{link:alliance}联盟{/link}的所有饱学之士中，他住得离{link:ruins-of-alterac}奥特兰克废墟{/link}最近。他为那个陷落王国的图书馆而悲伤。每当有一封奇怪的信件或一张附有魔法的羊皮纸从山上传下来，都会被送到他这里。]=],
		},
		{
			title = "意义",
			text = [=[迪布斯是{link:southshore}南海镇{/link}的记忆，也是它的解谜人。{link:alterac-mountains}奥特兰克{/link}遗失的书籍和{link:syndicate}辛迪加{/link}的密信都经过他的手。他知道自己学识的局限，也知道该向谁请教。]=],
		},
		{
			title = "事迹",
			text = [=[• 他指挥人们搜寻被{link:ogres}食人魔{/link}从{link:ruins-of-alterac}奥特兰克废墟{/link}中掠走的书籍。
• 他寻找《格里{link:farmer-ray}雷{/link}克之臂》，一本记载古老{link:trolls}巨魔{/link}学识的书，废墟中藏有已知最后一部完整的抄本。
• 他把找回的书送给{link:milton-sheaf}米尔顿·西弗{/link}，收入{link:stormwind-city}暴风城{/link}的{link:royal-library}皇家图书馆{/link}。
• 他把{link:syndicate}辛迪加{/link}的密码信送给{link:ironforge}铁炉堡{/link}的{link:prospector-stormpike}勘察员塔伯斯·雷矛{/link}。]=],
		},
	},
	chapters = {
		{
			title = "奥特兰克之书",
			hint = "为博学者找回奥特兰克的典籍。",
			text = [=[{link:alterac-mountains}奥特兰克{/link}在陷落前有一座宏伟的图书馆。如今{link:crushridge-ogres}破碎岭食人魔{/link}住在它的废墟中，而对他们来说，书除了烧掉或踩烂之外毫无用处。迪布斯年纪太大，爬不上山。于是别人代他前往，带回{link:ogres}食人魔{/link}尚未毁掉的东西。他留下《格里{link:farmer-ray}雷{/link}克之臂》来研究，把其余的书送往{link:stormwind-city}暴风城{/link}。]=],
		},
		{
			title = "密文信件",
			hint = "把在辛迪加那里找到的密码交给博学者。",
			text = [=[在{link:syndicate}辛迪加{/link}盗贼身上找到的信是用一种迪布斯从未见过的密码写成的。他坦白承认了这一点，并把信转给了他在{link:ironforge}铁炉堡{/link}的朋友。当它终于被读懂时，信中提到辛迪加背后另有一股力量，与{link:alterac-mountains}奥特兰克{/link}的贵族毫不相干。]=],
		},
	},
	mentions = {
		{
			text = [=[{link:southshore}南海镇{/link}，受{link:milton-sheaf}米尔顿·西弗{/link}派遣]=],
		},
		{ text = "保存知识" },
		{ text = "回到{link:milton-sheaf}米尔顿{/link}身边" },
		{ text = "密文信件" },
		{ text = "给{link:stormpike-guard}雷矛{/link}的信" },
		{ text = "附魔的羊皮纸" },
		{ text = "{link:stormpike-guard}雷矛{/link}的破译" },
	},
	bonds = {
		{ id = "milton-sheaf", name = "米尔顿·西弗", note = "暴风城的图书管理员" },
		{ id = "prospector-stormpike", name = "勘察员塔伯斯·雷矛", note = "破译他的密码" },
		{ id = "magistrate-henry-maleb", name = "赫尼·马雷布镇长", note = "接收信中揭示的内容" },
	},
})

Translate("zhCN", "magistrate-henry-maleb", {
	title = "赫尼·马雷布镇长",
	subtitle = "南海镇法官",
	found = "南海镇市政厅",
	hint = "与治理南海镇的法官交谈。",
	allegiance = "南海镇 · 联盟",
	aliases = { "马雷布", "马雷布镇长" },
	sections = {
		{
			title = "概述",
			text = [=[赫尼·马雷布治理着{link:southshore}南海镇{/link}。上一任法官被刺客谋杀，凶手至今未被抓获，他随后接任了这一职务。他的调查指向了{link:syndicate}辛迪加{/link}，那是{link:alterac-mountains}奥特兰克{/link}失势贵族的{link:alliance}联盟{/link}。随后，人们发现了一份要取他性命的契约，上面盖着一位贵族的戒指印。]=],
		},
		{
			title = "事迹",
			text = [=[• 他派战士攻打{link:tarren-mill}塔伦米尔{/link}以北和{link:strahnbrad}斯坦恩布莱德{/link}的{link:syndicate}辛迪加{/link}营地。
• 他索要辛迪加那些隐身幕后的贵族的图章戒指。
• 他悬赏{link:baron-vardus}瓦杜斯男爵{/link}，正是这位领主签署了他的死刑令。]=],
		},
	},
	chapters = {
		{
			title = "阿古斯之痕",
			hint = "循着辛迪加的信件追查其源头。",
			text = [=[被破译的信件既非出自盗贼之手，也非出自贵族之手。写信的人名叫{link:nagaz}纳伽兹{/link}，效力于一个叫作阿古斯之痕的组织。马雷布派人追杀了他，但他担心纳伽兹只是某个更强大力量的仆从。]=],
		},
	},
	mentions = {
		{ text = "{link:syndicate}辛迪加{/link}刺客" },
		{ text = "预备行动计划" },
		{ text = "贵族之死" },
		{ text = "刺客的契约" },
		{ text = "{link:the-baron}男爵{/link}之死" },
		{ text = "更大的谜团" },
		{ text = "黑暗{link:shadow-council}议会{/link}" },
	},
	bonds = {
		{ id = "loremaster-dibbs", name = "博学者迪布斯", note = "解读那些信件" },
		{ id = "marshal-redpath", name = "治安官雷德帕斯", note = "统领他的卫兵" },
	},
})

Translate("zhCN", "marshal-redpath", {
	title = "治安官雷德帕斯",
	subtitle = "南海镇元帅",
	found = "南海镇",
	hint = "与统领南海镇卫兵的元帅交谈。",
	allegiance = "南海镇 · 联盟",
	aliases = { "雷德帕斯" },
	sections = {
		{
			title = "概述",
			text = [=[治安官雷德帕斯统领着{link:southshore}南海镇{/link}的卫兵。他留意着小镇面临的每一个威胁：{link:western-strand}西部海岸{/link}的{link:murlocs}鱼人{/link}，{link:eastern-strand}东部海滩{/link}的{link:naga}纳迦{/link}，还有那些若是不受打扰就可能从{link:alterac-mountains}奥特兰克{/link}下山的{link:crushridge-ogres}破碎岭食人魔{/link}。他要求拿出证据，并为此付钱。]=],
		},
		{
			title = "事迹",
			text = [=[• 他悬赏{link:crushridge-ogres}破碎岭食人魔{/link}的指骨。
• 他命令{link:lieutenant-farren-orinelle}法尔林·奥里涅尔中尉{/link}去对付{link:murlocs}鱼人{/link}，然后又去对付{link:naga}纳迦{/link}。]=],
		},
		{
			title = "未载",
			text = [=[{link:second-war}第二次战争{/link}的史书记载，{link:stormwind-city}暴风城{/link}的难民登岸时，{link:southshore}南海镇{/link}的镇长名叫马库斯·雷德帕斯。这位元帅或许就是那个人。另有一个同姓的家族，即{link:darrowshire}达隆郡{/link}的雷德帕斯一家，其中有小{link:pamela-redpath}帕米拉·雷德帕斯{/link}，他们生活在遥远的东方。没有任何记载说明他与他们是否有亲缘关系。]=],
		},
	},
	mentions = {
		{ text = "{link:crushridge-ogres}破碎岭{/link}的悬赏" },
		{ text = "{link:crushridge-ogres}破碎岭{/link}的战争贩子" },
		{ text = "法伦的证据" },
	},
	bonds = {
		{ id = "lieutenant-farren-orinelle", name = "法尔林·奥里涅尔中尉", note = "他那不情不愿的军官" },
		{ id = "magistrate-henry-maleb", name = "赫尼·马雷布镇长", note = "治理他所守卫的小镇" },
	},
})

Translate("zhCN", "lieutenant-farren-orinelle", {
	title = "法尔林·奥里涅尔中尉",
	subtitle = "南海镇的军官",
	found = "南海镇旅店",
	hint = "寻找那位整天待在南海镇旅店里的中尉。",
	allegiance = "暴风城卫兵 · 南海镇",
	aliases = { "法尔林·奥瑞尼尔", "法尔林" },
	sections = {
		{
			title = "概述",
			text = [=[法尔林·奥瑞尼尔原是{link:stormwind-city}暴风城{/link}的一名卫兵，后来被派往北方的{link:southshore}南海镇{/link}。他讨厌这座小镇，讨厌港口的气味，也讨厌上级命令他去打的{link:murlocs}鱼人{/link}。他大部分时间都端着杯子待在旅店里，梦想着回家。]=],
		},
