			hint = "把药剂师的瘟疫酒送给被俘的农民。",
			text = [=[最后一种药剂需要{link:nethander-stead}奈杉德哨岗{/link}那些恶臭的花、{link:master-apothecary-faranell}法拉尼尔{/link}亲手制作的胶质，以及一桶来自{link:dun-garok}丹加洛克{/link}的{link:dwarves}矮人{/link}黑啤酒。随后林度恩让人把这桶被污染的酒放进{link:forsaken}被遗忘者{/link}关押被俘农民的房间里。他称之为给他们办一场派对。]=],
		},
	},
	mentions = {
		{
			text = [=[前往{link:hillsbrad-foothills}希尔斯布莱德丘陵{/link}，来自{link:apothecary-renferrel}药剂师伦弗利尔{/link}]=],
