Translate("zhCN", "battle-of-hillsbrad", {
	title = "希尔斯布莱德之战",
	sections = {
		{
			title = "概述",
			text = [=[希尔斯布莱德之战是{link:tarren-mill}塔伦米尔{/link}的{link:forsaken}被遗忘者{/link}如今向丘陵中的{link:humans}人类{/link}发动的战争。它的目的很明确：在药剂师完成新瘟疫之前击垮{link:hillsbrad-foothills}希尔斯布莱德{/link}的人类，然后将{link:southshore}南海镇{/link}夷为平地。]=],
		},
		{
			title = "战役",
			text = [=[命令由{link:varimathras}瓦里玛萨斯{/link}下达给{link:high-executor-darthalia}高级执行官达萨利亚{/link}。当她在{link:southpoint-tower}南点哨塔{/link}的斥候传来消息，说小镇已经可以下手时，进攻便分阶段展开了。

• {b}农场。{/b}亡灵卫兵首先袭击北方的农场和它们的主人，以切断{link:hillsbrad-foothills}希尔斯布莱德{/link}的粮食。
• {b}果园。{/b}逃进南方果园的农民在那里遭到追杀。
• {b}铁匠铺。{/b}铁匠和他的学徒被杀，小镇的铁料被运走。
• {b}{link:shadow-council}议会{/link}。{/b}法官和议会被列入死亡名单，小镇的宪章要被焚毁，名册要被偷走。
• {b}矿洞。{/b}{link:azurelode-mine}碧玉矿洞{/link}的工头和矿工遭到袭击，好让{link:sylvanas-windrunner}黑暗女王{/link}用那里的铁武装她的士兵。
• {b}{link:dun-garok}丹加洛克{/link}。{/b}最后是对{link:thoradin-s-wall}索拉丁之墙{/link}上那座{link:dwarves}矮人{/link}要塞的围攻。]=],
		},
		{
			title = "另一方",
			text = [=[{link:humans}人类{/link}并没有默默死去。{link:hillsbrad-foothills}希尔斯布莱德{/link}的镇民杀死了{link:forsaken}被遗忘者{/link}的卫兵、药剂师和亡灵{link:sentinels}哨兵{/link}，还伏击了从{link:undercity}幽暗城{/link}送来的补给。{link:high-executor-darthalia}达萨利亚{/link}把他们的名字列在一份悬赏名单上。]=],
		},
		{
			title = "药剂师",
			text = [=[士兵们作战之时，{link:apothecary-lydon}药剂师林度恩{/link}在{link:hillsbrad-foothills}希尔斯布莱德{/link}的狗和被俘的农民身上试验他的药剂。每一种都是迈向{link:sylvanas-windrunner}黑暗女王{/link}所下令研制的瘟疫的一步。]=],
		},
	},
})

Translate("zhCN", "internment-camps", {
	title = "收容所",
	aliases = { "兽人收容所" },
	sections = {
		{
			title = "概述",
			text = [=[{link:second-war}第二次战争{/link}之后，幸存的{link:orcs}兽人{/link}没有被斩尽杀绝。他们被集中到遍布{link:lordaeron}洛丹伦{/link}的收容所中，由{link:alliance}联盟{/link}的士兵看守。收容所本意是关押战败之敌的地方。它们却变成了更糟的东西。]=],
		},
		{
			title = "消沉",
			text = [=[与曾经驱使他们的恶魔之力断绝之后，收容所中的{link:orcs}兽人{/link}变得萎靡不振，心灵病弱。许多兽人只是坐在墙内，不再尝试离开。看守他们的{link:humans}人类{/link}无法理解这一点。有些人可怜他们。另一些人则从他们身上牟利。]=],
		},
		{
			title = "敦霍尔德",
			text = [=[收容所由{link:hillsbrad-foothills}希尔斯布莱德{/link}的{link:durnholde-keep}敦霍尔德城堡{/link}统辖，由中将{link:aedelas-blackmoore}埃德拉斯·布莱克摩尔{/link}掌管。布莱克摩尔在他的城墙后看到的不只是囚犯。他看到了一支可以归他所有的军队，只要由他亲手养大的一个{link:orcs}兽人{/link}来率领它。]=],
		},
		{
			title = "解放",
			text = [=[那个{link:orcs}兽人{/link}就是{link:thrall}萨尔{/link}。他逃出{link:durnholde-keep}敦霍尔德{/link}，找到了自由的氏族，学会了萨满之道。在{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}的辅佐下，他逐一攻打收容所，解放了其中的兽人。毁灭之锤在其中一场战斗中倒下。最终萨尔来到了敦霍尔德本身，收容所也随之终结。]=],
		},
	},
})
